import { readSync, writeSync } from "node:fs";
import { encodeJSON, type Schema } from "/Users/vince/Projects/can-lang/runtime/codec/json.ts";
import { CodecIssue } from "/Users/vince/Projects/can-lang/runtime/codec/budget.ts";
import { copyBytes } from "/Users/vince/Projects/can-lang/runtime/bytes.ts";

// Fixed PM-N2 source-module subject. The parent owns all expectations and cleanup.
const mode = process.argv[2];
const schema: Schema = {
  root: "a",
  nodes: [
    { identity: "a", kind: "array", name: "array", element: "int" },
    { identity: "int", kind: "primitive", name: "int" },
  ],
};
const origin = { source: "probe:codec", start: 0, end: 0, invocation: [] };
const getterMarker = "n2-index-getter";
const handles = new Map<number, unknown[]>();
let sequence = 0;
let requests = 0;
let getterCalls = 0;
let witnessed = false;
let encoded = false;
let currentId: number | null = null;

function send(frame: Record<string, unknown>): void {
  const bytes = Buffer.from(JSON.stringify({ sequence: sequence++, ...frame }) + "\n");
  let offset = 0;
  while (offset < bytes.length) offset += writeSync(1, bytes, offset, bytes.length - offset);
}

function nextLine(): string | null {
  const byte = Buffer.allocUnsafe(1);
  let line = "";
  while (line.length <= 4096) {
    const count = readSync(0, byte, 0, 1, null);
    if (count === 0) return line.length === 0 ? null : line;
    if (byte[0] === 10) return line;
    line += String.fromCharCode(byte[0]);
  }
  throw new Error("request_too_large");
}

function requireRequest(line: string): { id: number; op: string; handle?: number } {
  const value: unknown = JSON.parse(line);
  if (value === null || typeof value !== "object" || Array.isArray(value))
    throw new Error("invalid_request");
  const request = value as Record<string, unknown>;
  if (typeof request.id !== "number" || !Number.isSafeInteger(request.id) || typeof request.op !== "string")
    throw new Error("invalid_request");
  return request as { id: number; op: string; handle?: number };
}

if (mode !== "positive" && mode !== "control") throw new Error("invalid_mode");
send({ id: null, event: "ready", mode });

try {
  while (true) {
    const line = nextLine();
    if (line === null) throw new Error("missing_close");
    if (++requests > 4) throw new Error("request_limit");
    const request = requireRequest(line);
    currentId = request.id;
    let facts: Record<string, unknown>;
    switch (request.op) {
      case "witness": {
        if (witnessed) throw new Error("duplicate_witness");
        witnessed = true;
        const bytes = copyBytes(encodeJSON(schema, [1n]), origin);
        facts = { encodedHex: Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("") };
        break;
      }
      case "make_array": {
        if (!witnessed || handles.size !== 0) throw new Error("invalid_make");
        const hostile: unknown[] = [];
        Object.defineProperty(hostile, 0, {
          enumerable: true,
          get() {
            getterCalls++;
            throw new Error(getterMarker);
          },
        });
        handles.set(1, hostile);
        facts = { handle: 1, calls: getterCalls };
        break;
      }
      case "encode": {
        if (request.handle !== 1 || handles.size !== 1 || encoded) throw new Error("invalid_encode");
        encoded = true;
        let controlMarker: string | null = null;
        if (mode === "control") {
          try {
            void handles.get(1)![0];
          } catch (error) {
            controlMarker = error instanceof Error ? error.message : "non_error";
          }
        }
        let issue: CodecIssue | null = null;
        let invoked = false;
        try {
          invoked = true;
          encodeJSON(schema, handles.get(1)!);
        } catch (error) {
          if (!(error instanceof CodecIssue)) throw error;
          issue = error;
        }
        facts = {
          reason: issue?.reason ?? null,
          path: issue?.path ?? null,
          calls: getterCalls,
          invoked,
          controlMarker,
        };
        break;
      }
      case "close": {
        send({ id: request.id, event: "reply", op: request.op, facts: { calls: getterCalls }, seal: true });
        handles.clear();
        process.exit(0);
      }
      default:
        throw new Error("unknown_operation");
    }
    send({ id: request.id, event: "reply", op: request.op, facts });
    currentId = null;
  }
} catch (error) {
  const message = error instanceof Error ? error.message : "non_error";
  send({ id: currentId, event: "error", message: message.slice(0, 96) });
  process.exitCode = 1;
}

