// PM-B1 temporary native mechanics driver. The external Python parent owns Chrome and cleanup.
import { writeSync } from "node:fs";
import { createInterface } from "node:readline";
import { chromium } from "/Users/vince/Projects/can-lang/node_modules/playwright/index.mjs";

type Command = Record<string, unknown> & { event?: string; id?: string };
type RouteDecision = { marker: string } | null;

let seq = 0;
let operationId = "";
let mode: "positive" | "control" | null = null;
let browser: any = null;
let context: any = null;
let page: any = null;
let clickPromise: Promise<void> | null = null;
let clickOutcome: "pending" | "fulfilled" | "rejected" | "unstarted" = "unstarted";
let inputId = "";
let routeOutcome: "unseen" | "pending" | "fulfilled" | "aborted" | "failed" = "unseen";
let routeTask: Promise<void> | null = null;
let pending: { token: string; decide: (decision: RouteDecision) => void } | null = null;
let routeCount = 0;
let diagnosticCount = 0;
let closing = false;
let finished = false;

function emit(event: string, id: string, facts: Record<string, unknown> = {}): void {
  const frame = {
    seq: ++seq,
    timeNs: process.hrtime.bigint().toString(),
    event,
    id,
    operationId,
    ...facts,
  };
  writeSync(1, JSON.stringify(frame) + "\n");
}

function shortError(error: unknown): string {
  const message = error instanceof Error ? `${error.name}: ${error.message}` : String(error);
  return message.slice(0, 1024);
}

function diagnostic(event: string, error: unknown): void {
  diagnosticCount += 1;
  emit(event, operationId, { message: shortError(error) });
}

function stringField(command: Command, field: string, max = 2048): string {
  const value = command[field];
  if (typeof value !== "string" || value.length === 0 || value.length > max) {
    throw new Error(`invalid ${field}`);
  }
  return value;
}

function htmlEscape(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

async function onRoute(route: any): Promise<void> {
  routeCount += 1;
  const request = route.request();
  const token = `${operationId}:route:${routeCount}`;
  if (closing || routeCount !== 1) {
    diagnostic("route_error", new Error("unexpected route or closing"));
    try {
      await route.abort();
    } catch (error) {
      diagnostic("route_abort_error", error);
    }
    return;
  }
  routeOutcome = "pending";
  const decision = new Promise<RouteDecision>((decide) => {
    pending = { token, decide };
  });
  emit("route_arrived", inputId || operationId, {
    token,
    method: request.method(),
    path: new URL(request.url()).pathname,
    postDataLength: request.postDataBuffer()?.length ?? 0,
  });
  const result = await decision;
  pending = null;
  try {
    if (result === null || closing) {
      await route.abort();
      routeOutcome = "aborted";
      emit("route_aborted", operationId, { token });
    } else {
      await route.fulfill({
        status: 200,
        contentType: "text/html; charset=utf-8",
        body: `<!doctype html><html><body><div id="result">${htmlEscape(result.marker)}</div></body></html>`,
      });
      routeOutcome = "fulfilled";
      emit("resolved", operationId, { token, marker: result.marker });
    }
  } catch (error) {
    routeOutcome = "failed";
    diagnostic("route_error", error);
  }
}

async function start(command: Command): Promise<void> {
  if (browser || operationId || closing) throw new Error("start already attempted");
  operationId = stringField(command, "id", 128);
  const endpoint = stringField(command, "endpoint");
  const url = stringField(command, "url");
  if (command.mode !== "positive" && command.mode !== "control") {
    throw new Error("invalid mode");
  }
  mode = command.mode;
  const origin = new URL(url).origin;
  browser = await chromium.connectOverCDP(endpoint, { timeout: 10_000 });
  context = await browser.newContext();
  page = await context.newPage();
  page.on("pageerror", (error: unknown) => diagnostic("page_error", error));
  page.on("requestfailed", (request: any) => {
    if (!closing) diagnostic("request_failed", request.failure()?.errorText ?? "request failed");
  });
  page.on("response", (response: any) => {
    if (new URL(response.url()).pathname === "/held") {
      emit("response_observed", inputId || operationId, {
        status: response.status(),
        path: "/held",
      });
    }
  });
  await context.route(origin + "/held", (route: any) => {
    routeTask = onRoute(route);
    return routeTask;
  });
  await page.goto(url, { waitUntil: "domcontentloaded", timeout: 10_000 });
  emit("prepared", operationId, { mode, origin });
}

function input(command: Command): void {
  const id = stringField(command, "id", 128);
  if (!page || clickPromise || closing) throw new Error("input unavailable");
  inputId = id;
  clickOutcome = "pending";
  clickPromise = page.click("#submit", { timeout: 30_000 });
  // These handlers attach to the actual Playwright promise, not a delayed RPC wrapper.
  void clickPromise.then(
    async () => {
      clickOutcome = "fulfilled";
      emit("input_settled", id, { status: "fulfilled" });
      if (closing) return; // Cleanup preserves settlement facts but has no delivered marker to inspect.
      try {
        const marker = await page.locator("#result").textContent({ timeout: 5_000 });
        emit("observation", id, { marker });
      } catch (error) {
        diagnostic("observation_error", error);
      }
    },
    (error) => {
      clickOutcome = "rejected";
      emit("input_settled", id, { status: "rejected", message: shortError(error) });
    },
  );
}

function ping(command: Command): void {
  const id = stringField(command, "id", 128);
  const respond = () => {
    if (closing) return;
    emit("pong", id);
  };
  if (mode === "control") {
    if (!clickPromise) throw new Error("control ping before input");
    void clickPromise.then(respond, respond);
  } else {
    respond();
  }
}

function resolve(command: Command): void {
  const id = stringField(command, "id", 128);
  const token = stringField(command, "token", 256);
  const marker = stringField(command, "marker", 128);
  const deliver = () => {
    if (closing) return;
    if (!pending || pending.token !== token) {
      emit("protocol_error", id, { message: "unknown or spent route token" });
      return;
    }
    const selected = pending;
    pending = null;
    emit("resolve_received", id, { token, marker });
    selected.decide({ marker });
  };
  if (mode === "control") {
    if (!clickPromise) throw new Error("control resolve before input");
    void clickPromise.then(deliver, deliver);
  } else {
    deliver();
  }
}

async function teardown(): Promise<void> {
  closing = true;
  if (pending) {
    const selected = pending;
    pending = null;
    selected.decide(null);
  }
  const errors: string[] = [];
  // For a CDP-connected Browser, Playwright's browser.close() sends a browser
  // close command. The parent owns Chrome; this process exit drops only its CDP
  // transport after the owned context is closed.
  if (routeTask) {
    try {
      await routeTask;
    } catch (error) {
      errors.push("route: " + shortError(error));
    }
  }
  if (context) {
    try {
      await context.close();
    } catch (error) {
      errors.push("context: " + shortError(error));
    }
  }
  for (const error of errors) diagnostic("close_error", error);
}

async function finish(command: Command): Promise<void> {
  const id = stringField(command, "id", 128);
  if (finished || closing) return;
  if (clickOutcome === "pending" || clickOutcome === "unstarted" || routeOutcome === "pending") {
    throw new Error("finish before terminal input and route");
  }
  await teardown();
  finished = true;
  emit("seal", id, { clickOutcome, routeOutcome, routeCount, diagnosticCount, pendingRoute: pending !== null });
  process.exit(0);
}

async function close(command: Command): Promise<void> {
  const id = stringField(command, "id", 128);
  if (finished) return;
  emit("closing", id, { clickOutcome, routeOutcome, pendingRoute: pending !== null });
  await teardown();
  finished = true;
  emit("closed", id, { clickOutcome, routeOutcome, routeCount, diagnosticCount, pendingRoute: pending !== null });
  process.exit(0);
}

async function dispatch(command: Command): Promise<void> {
  const event = stringField(command, "event", 32);
  if (closing && event !== "close") return;
  switch (event) {
    case "start":
      await start(command);
      break;
    case "input":
      input(command);
      break;
    case "ping":
      ping(command);
      break;
    case "resolve":
      resolve(command);
      break;
    case "finish":
      await finish(command);
      break;
    case "close":
      await close(command);
      break;
    default:
      throw new Error("unknown command");
  }
}

emit("ready", "");
const lines = createInterface({ input: process.stdin, crlfDelay: Infinity });
for await (const line of lines) {
  if (line.length > 16_384) {
    diagnostic("protocol_error", new Error("command too large"));
    continue;
  }
  let command: Command;
  try {
    command = JSON.parse(line);
    if (command === null || typeof command !== "object" || Array.isArray(command)) {
      throw new Error("command is not an object");
    }
  } catch (error) {
    diagnostic("protocol_error", error);
    continue;
  }
  void dispatch(command).catch((error) => {
    emit("protocol_error", typeof command.id === "string" ? command.id : "", {
      message: shortError(error),
    });
  });
}
if (!finished) {
  await teardown();
  emit("stdin_closed", operationId, { clickOutcome, routeOutcome, diagnosticCount });
  process.exit(0);
}

