import hashlib, http.server, re, select, socket, subprocess, sys, threading

REPO=pathlib.Path('/Users/vince/Projects/can-lang')
BUN=REPO/'.local-deps/pinned/bun-darwin-aarch64/bun'
CHROME=pathlib.Path('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome')
REPORT={'kind':'can.preparatory.execution','run_id':RUN_ID,'integrated_qualification':False,'jobs':[]}
PROCS=[]; FDS=set(); KNOWN={}; CURRENT=None; SERVER=None; THREAD=None
START=time.monotonic(); BATCH_END=START+135
class CheckFailure(Exception): pass
class Blocked(Exception): pass
class Inconclusive(Exception): pass
def require(ok, message):
    if not ok: raise CheckFailure(message)
def alarm(signum,frame): raise TimeoutError('external deadline')
signal.signal(signal.SIGALRM,alarm)
signal.setitimer(signal.ITIMER_REAL,135)
def sha(path):
    h=hashlib.sha256()
    with pathlib.Path(path).open('rb') as f:
        for b in iter(lambda:f.read(1048576),b''): h.update(b)
    return h.hexdigest()
def tree_identity(path):
    entries=[]; size=0
    for directory,dirs,files in os.walk(path,followlinks=False):
        for name in sorted(files+dirs):
            p=pathlib.Path(directory)/name
            if p.is_symlink(): entries.append((str(p.relative_to(path)),'link:'+os.readlink(p)))
            elif p.is_file():
                size+=p.stat().st_size
                entries.append((str(p.relative_to(path)),sha(p)))
    return {'files':len(entries),'bytes':size,'manifest_sha256':hashlib.sha256(json.dumps(sorted(entries),separators=(',',':')).encode()).hexdigest()}
def process_table():
    raw=subprocess.run(['/bin/ps','-axo','pid=,ppid=,pgid=,rss=,lstart=,command='],capture_output=True,timeout=2)
    if raw.returncode or len(raw.stdout)>2*1024*1024: raise Blocked('process observation unavailable/oversize')
    rows={}
    for line in raw.stdout.decode(errors='replace').splitlines():
        a=line.split(None,9)
        if len(a)==10:
            rows[int(a[0])]={'ppid':int(a[1]),'pgid':int(a[2]),'rss_kib':int(a[3]),'start':' '.join(a[4:9]),'command':a[9]}
    return rows
def owned_rows(rows):
    ids={p.pid for p in PROCS if p.poll() is None}
    for pid,item in KNOWN.items():
        if pid in rows and rows[pid]['start']==item['start']: ids.add(pid)
    changed=True
    while changed:
        new={pid for pid,r in rows.items() if r['ppid'] in ids}
        changed=not new<=ids; ids|=new
    for pid in ids:
        if pid in rows and pid!=os.getpid(): KNOWN.setdefault(pid,rows[pid])
    ids.add(os.getpid())
    return {pid:rows[pid] for pid in ids if pid in rows}
def monitor(force=False):
    if CURRENT is None: return
    now=time.monotonic()
    if now>CURRENT['effect_end']: raise TimeoutError('job work budget exhausted; cleanup reserved')
    if not force and now-CURRENT.get('last_sample',0)<.25: return
    CURRENT['last_sample']=now
    for p in PROCS:
        if getattr(p,'role',None)=='Chrome':
            for stream in [p.stdout,p.stderr]:
                if stream.closed: continue
                while True:
                    try: data=os.read(stream.fileno(),4096)
                    except BlockingIOError: break
                    if not data: break
                    io_charge(len(data));p.error+=data
                    require(len(p.error)<=32768,'Chrome diagnostic cap exceeded')
    rows=owned_rows(process_table())
    rss=sum(r['rss_kib'] for r in rows.values())*1024
    size=sum(p.stat().st_size for p in ROOT.rglob('*') if p.is_file() and not p.is_symlink())
    CURRENT['peak_rss_bytes']=max(CURRENT.get('peak_rss_bytes',0),rss)
    CURRENT['peak_processes']=max(CURRENT.get('peak_processes',0),len(rows)+1)
    CURRENT['peak_scratch_bytes']=max(CURRENT.get('peak_scratch_bytes',0),size)
    require(len(rows)+1<=CURRENT['process_cap'],'process ceiling exceeded')
    require(rss<=CURRENT['rss_cap'],'RSS stop threshold exceeded')
    require(size<=CURRENT['scratch_cap'],'scratch stop threshold exceeded')
def io_charge(n):
    if CURRENT is not None:
        CURRENT['io_bytes']=CURRENT.get('io_bytes',0)+n
        require(CURRENT['io_bytes']<=CURRENT['io_cap'],'I/O ceiling exceeded')
def env_for(work):
    return {'HOME':str(work/'home'),'XDG_CONFIG_HOME':str(work/'config'),'TMPDIR':str(work/'tmp'),'PATH':'/nonexistent'}
def workdir(name):
    path=ROOT/name
    STATE.setdefault('allocations',[]).append({'directory':str(path),'cleanup':'T removes after child release'});save_state()
    path.mkdir(mode=0o700)
    for x in ['home','config','tmp','cwd']: (path/x).mkdir(mode=0o700)
    return path
def bun_args(file,mode=None):
    args=[str(BUN),'--no-install','--no-env-file','--no-macros','--config='+str(REPO/'tools/runtime/bunfig.toml'),str(ROOT/file),'--']
    if mode is not None: args.append(mode)
    return args
def register(p,role):
    PROCS.append(p); STATE['safe_to_remove']=False
    STATE.setdefault('children',[]).append({'pid':p.pid,'role':role,'group':p.pid});save_state()
    p.role=role;p.frames=[];p.buffer=b'';p.error=b'';p.last_seq=None;p.trace=[];p.stdout_eof=False
    for f in [p.stdout,p.stderr]:
        os.set_blocking(f.fileno(),False)
    monitor(True)
    return p
def launch(file,mode,work):
    STATE.setdefault('spawn_intents',[]).append({'role':file,'work':str(work),'group':'new session','descendants':'none'});save_state()
    prior=signal.pthread_sigmask(signal.SIG_BLOCK,{signal.SIGINT,signal.SIGTERM})
    try:
        p=subprocess.Popen(bun_args(file,mode),stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,cwd=work/'cwd',env=env_for(work),start_new_session=True,bufsize=0)
        register(p,file)
    finally: signal.pthread_sigmask(signal.SIG_SETMASK,prior)
    return p
def pump(p):
    monitor()
    for f in [p.stdout,p.stderr]:
        if f.closed: continue
        while True:
            try: b=os.read(f.fileno(),4096)
            except BlockingIOError: break
            if not b:
                if f is p.stdout: p.stdout_eof=True
                break
            io_charge(len(b))
            if f is p.stderr:
                p.error+=b; require(len(p.error)<=32768,'stderr capture exceeded')
            else:
                p.buffer+=b;require(len(p.buffer)<=8192,'oversize or unterminated frame')
                while b'\n' in p.buffer:
                    line,p.buffer=p.buffer.split(b'\n',1)
                    frame=json.loads(line)
                    require(isinstance(frame,dict),'frame must be object')
                    seq=frame.get('seq',frame.get('sequence'))
                    if seq is not None:
                        require(seq==(0 if 'sequence' in frame else 1) if p.last_seq is None else seq==p.last_seq+1,'sequence gap/duplicate');p.last_seq=seq
                    p.trace.append({'received_ns':time.monotonic_ns(),'frame':frame})
                    p.frames.append(frame);require(len(p.frames)<=64,'event limit exceeded')
    p.poll()
def wait_for(p,predicate,timeout=5):
    end=min(time.monotonic()+timeout,CURRENT['effect_end'])
    while True:
        pump(p)
        match=next((f for f in p.frames if predicate(f)),None)
        if match is not None: return match
        if p.poll() is not None:
            pump(p); match=next((f for f in p.frames if predicate(f)),None)
            if match is not None: return match
            raise CheckFailure('child exited before observation: '+p.error.decode(errors='replace')[:1000])
        if time.monotonic()>=end: raise TimeoutError('observation deadline')
        time.sleep(.015)
def send(p,data):
    if p.role=='browser-driver.ts': data={**data,'event':data['op'],'id':str(data['id'])};data.pop('op',None)
    p.trace.append({'sent_ns':time.monotonic_ns(),'frame':data})
    data=json.dumps(data,separators=(',',':')).encode()+b'\n';io_charge(len(data))
    require(len(data)<=4096,'request frame too large')
    require(os.write(p.stdin.fileno(),data)==len(data),'short request write')
def rpc(p,id,op,**fields):
    send(p,{'id':id,'op':op,**fields})
    frame=wait_for(p,lambda f:f.get('id')==id and f.get('event')=='reply')
    require(frame.get('op')==op,'operation mismatch')
    return {**frame.get('facts',{}),'seal':frame.get('seal')}
def finish_child(p,timeout=2):
    end=time.monotonic()+timeout
    while p.poll() is None and time.monotonic()<end:
        pump(p);time.sleep(.01)
    require(p.poll() is not None,'child did not exit')
    pump(p);require(p.returncode==0,'unexpected nonzero exit')
    require(not p.buffer,'partial final frame')
    return {'exit':p.returncode,'frames':p.frames,'trace':p.trace,'stderr':p.error.decode(errors='replace')}
def native():
    legs=[]
    CURRENT['observed_legs']=legs
    for mode in ['positive','control']:
        p=launch('native-subject.ts',mode,workdir('n1-'+mode));wait_for(p,lambda f:f.get('event')=='ready')
        made=rpc(p,1,'make_then_getter')
        alias=rpc(p,2,'alias',handle=1)
        first=rpc(p,3,'observe',handles=[1,2])
        second=rpc(p,4,'observe',handles=[1,2])
        read=rpc(p,5,'get_then',handle=1)
        sealed=rpc(p,6,'close')
        facts=finish_child(p)
        require(len(p.frames)==7 and not p.error,'native extra events/errors')
        require(made.get('calls')==0 and made.get('handle')==1,'construction witness')
        require(alias.get('handle')==2,'alias handle witness')
        expected=0 if mode=='positive' else 1
